package dev.darcosse.common.cobblemonsafari.biome;

import dev.darcosse.common.cobblemonsafari.CobblemonSafari;
import net.minecraft.core.registries.Registries;
import net.minecraft.resources.ResourceKey;
import net.minecraft.world.level.biome.Biome;

import java.util.List;
import java.util.Set;

/**
 * Keys of the Safari biomes, for code that needs to refer to one directly.
 *
 * <p>The biomes are data-driven and generated by
 * {@code tools/worldgen/generate_worldgen.py}; these constants must match its
 * BIOMES table. Spawn files should target the tags in {@link SafariBiomeTags},
 * not these keys, so habitats can be split or merged without touching spawns.
 */
public final class SafariBiomes {

    public static final ResourceKey<Biome> GRASSLAND = key("grassland");
    public static final ResourceKey<Biome> SAVANNA = key("savanna");
    public static final ResourceKey<Biome> DUNES = key("dunes");
    public static final ResourceKey<Biome> BADLANDS = key("badlands");
    public static final ResourceKey<Biome> JUNGLE = key("jungle");
    public static final ResourceKey<Biome> MARSH = key("marsh");
    public static final ResourceKey<Biome> FLOWER_MEADOW = key("flower_meadow");
    public static final ResourceKey<Biome> WOODLAND = key("woodland");
    public static final ResourceKey<Biome> DEEP_FOREST = key("deep_forest");
    public static final ResourceKey<Biome> TAIGA = key("taiga");
    public static final ResourceKey<Biome> SNOWFIELD = key("snowfield");
    public static final ResourceKey<Biome> GLACIER = key("glacier");
    public static final ResourceKey<Biome> ROCKY_HILLS = key("rocky_hills");
    public static final ResourceKey<Biome> MUSHROOM_GROVE = key("mushroom_grove");
    public static final ResourceKey<Biome> PEAKS = key("peaks");
    public static final ResourceKey<Biome> VOLCANIC = key("volcanic");
    public static final ResourceKey<Biome> LAKE = key("lake");
    public static final ResourceKey<Biome> RIVER = key("river");
    public static final ResourceKey<Biome> SHORE = key("shore");
    public static final ResourceKey<Biome> CAVERN = key("cavern");
    public static final ResourceKey<Biome> LUSH_GROTTO = key("lush_grotto");
    /** The giant cavern under the summit and the deep caves around it: the Safari's Deep Dark. */
    public static final ResourceKey<Biome> DEEP_CAVERN = key("deep_cavern");

    /**
     * Biomes found on the surface, where the mod itself spawns special Pokémon.
     * Caves are left out: the special spawner only samples the surface, so a
     * species assigned to a cave would never be met.
     */
    public static final List<ResourceKey<Biome>> SURFACE_HABITATS = List.of(
            GRASSLAND, SAVANNA, DUNES, BADLANDS, JUNGLE, MARSH, FLOWER_MEADOW, WOODLAND, DEEP_FOREST,
            TAIGA, SNOWFIELD, GLACIER, ROCKY_HILLS, MUSHROOM_GROVE, PEAKS, VOLCANIC, LAKE, RIVER, SHORE);

    /** Surface habitats made of open water, where water Pokémon spawn in the water itself. */
    public static final Set<ResourceKey<Biome>> WATER_HABITATS = Set.of(LAKE, RIVER);

    private SafariBiomes() {
    }

    /** Biome key in the mod namespace. */
    private static ResourceKey<Biome> key(String path) {
        return ResourceKey.create(Registries.BIOME, CobblemonSafari.id(path));
    }
}
